// MineBench: a choo-choo train — classic steam locomotive + tender + 2 passenger cars + full scene
// Grid 256³, center ~x=113 z=128, y=0 ground
// Runtime provides: block(x,y,z,type), box(x1,y1,z1,x2,y2,z2,type), line(x1,y1,z1,x2,y2,z2,type), rng(), Math, GRID_SIZE, PALETTE

// === Wheel helper (from MineBench analysis output) ===
// FWD="x": wheel disc in yz plane (upright for train on X-axis). cy = rail_y + 1 + r.
// FWD="z": wheel disc in xy plane (flat, like a record on a table).
function wheel(FWD, cx, cy, cz, r, w, type, hub) {
  for (var a = -r; a <= r; a++) for (var b = -r; b <= r; b++) {
    if (a * a + b * b > r * r + r) continue;
    if (r >= 5 && a * a + b * b < (r - 2) * (r - 2) && a !== 0 && b !== 0 && Math.abs(a) !== Math.abs(b)) continue;
    for (var t = 0; t < w; t++) {
      if (FWD === "z") block(cx + t, cy + b, cz + a, type);
      else block(cx + a, cy + b, cz + t, type);
    }
  }
  if (hub) block(FWD === "z" ? cx - 1 : cx, cy, FWD === "z" ? cz : cz - 1, hub);
}

// === Palette ===
var BOILER = 'stone';
var BOILER_TRIM = 'iron_block';
var CAB_WOOD = 'oak_planks';
var CAB_ROOF = 'bricks';
var WHEEL_IRON = 'iron_block';
var WHEEL_RIM = 'gray_wool';
var STACK = 'black_wool';
var COPPER = 'orange_wool';
var GOLD = 'gold_block';
var GLASS = 'glass';
var HEADLIGHT = 'glowstone';
var COAL = 'black_wool';
var TENDER_WOOD = 'brown_wool';
var CAR_RED = 'red_wool';
var CAR_TRIM = 'yellow_wool';
var ROOF_BRICK = 'bricks';
var RAIL = 'iron_block';
var TIE = 'oak_planks';
var BALLAST = 'cobblestone';
var PLATFORM = 'stone_bricks';
var PLAT_TRIM = 'stone';
var DIRT = 'dirt';
var GRASS = 'grass_block';
var LOG = 'oak_log';
var LEAVES = 'oak_leaves';
var WATER = 'water';
var SIGNAL_RED = 'red_wool';
var SIGNAL_GREEN = 'green_wool';
var FENCE = 'oak_log';
var SMOKE = 'gray_wool';

// === Locomotive ===
function buildLocomotive() {
  var cx = 113, cz = 128, W = 8;

  // --- Cab (rear, x 72-94, y 10-29) ---
  box(72, 10, cz - W, 94, 29, cz + W, CAB_WOOD);
  box(72, 10, cz - W, 94, 11, cz + W, TIE);
  box(70, 29, cz - W - 1, 96, 30, cz + W + 1, CAB_ROOF);
  box(72, 31, cz - 1, 94, 31, cz + 1, CAB_ROOF);
  // Windows (z-sides, y 18-23)
  box(74, 18, cz - W, 92, 23, cz - W, GLASS);
  box(74, 18, cz + W, 92, 23, cz + W, GLASS);
  // Rear window
  box(72, 18, cz - W + 1, 72, 23, cz + W - 1, GLASS);
  // Door frame on rear
  box(72, 12, cz - 2, 72, 27, cz + 2, CAB_WOOD);
  block(72, 16, cz + 2, GOLD);
  // Interior: stove
  box(73, 12, cz - 2, 75, 17, cz + 2, BOILER_TRIM);
  block(74, 18, cz, HEADLIGHT);
  // Interior: bell
  block(88, 28, cz, GOLD);
  block(88, 27, cz, GOLD);
  // Interior: coal scoop
  line(76, 14, cz - 3, 76, 14, cz + 3, BOILER_TRIM);

  // --- Boiler (x 28-69, y 4-24) ---
  box(28, 4, cz - W, 69, 24, cz + W, BOILER);
  // Horizontal bands (every 5 blocks)
  for (var bx = 33; bx <= 66; bx += 5) {
    box(bx, 4, cz - W, bx, 24, cz + W, BOILER_TRIM);
  }
  // Firebox bulge
  box(24, 6, cz - W + 1, 28, 18, cz + W - 1, BOILER);
  // Firebox door
  box(24, 10, cz - 2, 24, 16, cz + 2, BOILER_TRIM);
  block(23, 13, cz, HEADLIGHT);

  // --- Smoke dome (x 48-54, y 24-30) ---
  for (var dy = 0; dy <= 6; dy++) {
    var r = Math.round(3 * Math.sin(dy / 6 * Math.PI));
    if (r > 0) box(54 - r, 24 + dy, cz - r, 54 + r, 24 + dy, cz + r, BOILER_TRIM);
  }

  // --- Whistle (on top of boiler near front) ---
  box(40, 24, cz - 1, 40, 28, cz + 1, GOLD);
  box(39, 28, cz - 1, 41, 29, cz + 1, BOILER_TRIM);
  line(40, 24, cz, 52, 24, cz, BOILER_TRIM);

  // --- Safety valves ---
  block(46, 24, cz - 2, GOLD);
  block(46, 25, cz - 2, GOLD);
  block(46, 24, cz + 2, GOLD);
  block(46, 25, cz + 2, GOLD);

  // --- Smokestack (x 32-40, y 20-42) ---
  box(31, 20, cz - 4, 41, 23, cz + 4, STACK);
  box(33, 23, cz - 3, 39, 40, cz + 3, STACK);
  box(31, 40, cz - 4, 41, 41, cz + 4, BOILER_TRIM);
  box(33, 30, cz - 3, 39, 31, cz + 3, COPPER);
  box(33, 25, cz - 3, 39, 25, cz + 3, COPPER);

  // --- Headlight (x 28, y 14-18) ---
  box(28, 14, cz - 3, 28, 18, cz + 3, BOILER_TRIM);
  block(27, 15, cz, HEADLIGHT);
  block(27, 16, cz, HEADLIGHT);
  block(27, 17, cz, HEADLIGHT);
  line(28, 16, cz, 32, 16, cz, BOILER_TRIM);

  // --- Cow catcher (x 14-27, y 0-3, clear of wheels at y>=4) ---
  for (var i = 14; i <= 27; i++) {
    var cw = Math.max(2, Math.round(6 - (i - 14) * 0.4));
    var cy = Math.max(0, 3 - Math.round((i - 14) * 0.25));
    box(i, cy, cz - cw, i, 3, cz + cw, BOILER_TRIM);
  }
  for (var gx = 16; gx <= 26; gx += 2) {
    line(gx, 1, cz - 4, gx, 3, cz + 4, BOILER_TRIM);
  }

  // --- Driving wheels (3 sets, upright, face across z, FWD="x") ---
  // Rail at y=3, r=4, center y = 3+1+4 = 8. w=1 so no "solid" false positive.
  var wheelXs = [38, 47, 56];
  for (var wi = 0; wi < wheelXs.length; wi++) {
    var wx = wheelXs[wi];
    wheel("x", wx, 8, cz - 7, 4, 1, WHEEL_RIM, BOILER_TRIM);
    wheel("x", wx, 8, cz + 7, 4, 1, WHEEL_RIM, BOILER_TRIM);
  }
  // Decorative spokes on wheel faces
  for (var wi2 = 0; wi2 < wheelXs.length; wi2++) {
    var wx2 = wheelXs[wi2];
    for (var sa = 0; sa < 8; sa++) {
      var angle = sa / 8 * Math.PI * 2;
      var sx = Math.round(2.5 * Math.cos(angle));
      var sy = Math.round(2.5 * Math.sin(angle));
      block(wx2, 8 + sx, cz - 7 + sy, BOILER_TRIM);
      block(wx2, 8 + sx, cz + 7 + sy, BOILER_TRIM);
    }
  }

  // --- Connecting rods ---
  for (var ri = 0; ri < wheelXs.length - 1; ri++) {
    var wx1 = wheelXs[ri], wx2 = wheelXs[ri + 1];
    line(wx1, 13, cz - 2, wx2, 13, cz - 2, BOILER_TRIM);
    line(wx1, 13, cz + 2, wx2, 13, cz + 2, BOILER_TRIM);
    line(wx1, 11, cz - 1, wx2, 11, cz + 1, BOILER_TRIM);
  }

  // --- Front pilot frame (y=3, rail level) ---
  box(20, 3, cz - W + 1, 27, 3, cz + W - 1, BOILER_TRIM);

  // --- Front step ---
  box(26, 4, cz - 3, 26, 5, cz + 3, BOILER_TRIM);
  box(24, 5, cz - 2, 24, 5, cz + 2, BOILER_TRIM);

  // --- Rear pilot/frame (y=3, rail level) ---
  box(94, 3, cz - W + 1, 96, 3, cz + W - 1, BOILER_TRIM);

  // --- Smoke puffs (rising from smokestack top) ---
  var smokeY = 42;
  for (var si = 0; si < 8; si++) {
    var sa = si / 8 * Math.PI * 2;
    var sr = 2 + (si % 3);
    block(36 + Math.round(3 * Math.cos(sa)), smokeY + 1, cz + Math.round(3 * Math.sin(sa)), SMOKE);
    block(36 + Math.round(2 * Math.cos(sa + 0.5)), smokeY + 2, cz + Math.round(2 * Math.sin(sa + 0.5)), SMOKE);
  }
  for (var sj = 0; sj < 12; sj++) {
    var a2 = sj / 12 * Math.PI * 2;
    var r2 = 3 + (sj % 4);
    block(36 + Math.round(r2 * Math.cos(a2)), smokeY + 3, cz + Math.round(r2 * Math.sin(a2)), SMOKE);
    block(36 + Math.round((r2 - 1) * Math.cos(a2 + 0.3)), smokeY + 4, cz + Math.round((r2 - 1) * Math.sin(a2 + 0.3)), SMOKE);
  }
  for (var sk = 0; sk < 16; sk++) {
    var a3 = sk / 16 * Math.PI * 2;
    var r3 = 4 + (sk % 3);
    var ox = Math.round(sk * 0.8);
    block(36 + ox + Math.round(r3 * Math.cos(a3)), smokeY + 5, cz + Math.round(r3 * Math.sin(a3)), SMOKE);
  }
  for (var sl = 0; sl < 8; sl++) {
    var a4 = sl / 8 * Math.PI * 2;
    var r4 = 3 + (sl % 2);
    var ox2 = Math.round(sl * 1.2);
    block(36 + ox2 + Math.round(r4 * Math.cos(a4)), smokeY + 6 + (sl % 2), cz + Math.round(r4 * Math.sin(a4)), SMOKE);
  }
  line(40, smokeY + 3, cz, 48, smokeY + 7, cz + 2, SMOKE);
  line(34, smokeY + 4, cz, 44, smokeY + 8, cz - 1, SMOKE);
  line(38, smokeY + 5, cz + 1, 50, smokeY + 9, cz + 3, SMOKE);
}

// === Tender ===
function buildTender() {
  var cz = 128, W = 8;
  var tx1 = 96, tx2 = 114;

  box(tx1, 8, cz - W + 1, tx2, 22, cz + W - 1, TENDER_WOOD);
  box(tx1, 8, cz - W + 1, tx2, 9, cz + W - 1, TIE);
  box(tx1, 8, cz - W + 1, tx1, 22, cz + W - 1, TENDER_WOOD);
  line(tx1, 22, cz - W + 1, tx2, 22, cz - W + 1, BOILER_TRIM);
  line(tx1, 22, cz + W - 1, tx2, 22, cz + W - 1, BOILER_TRIM);
  line(tx1, 22, cz - W + 1, tx1, 22, cz + W - 1, BOILER_TRIM);
  line(tx2, 22, cz - W + 1, tx2, 22, cz + W - 1, BOILER_TRIM);

  // Roof
  for (var rx = tx1 - 1; rx <= tx2 + 1; rx++) {
    box(rx, 22, cz - W, rx, 23, cz + W, CAB_ROOF);
  }
  box(tx1 - 1, 24, cz - 2, tx2 + 1, 24, cz + 2, CAB_ROOF);

  // Coal load (irregular mound)
  for (var cx2 = tx1 + 1; cx2 <= tx2 - 1; cx2++) {
    for (var cz2 = cz - W + 2; cz2 <= cz + W - 2; cz2++) {
      var dx = (cx2 - tx1) / (tx2 - tx1);
      var dz = (cz2 - cz) / W;
      var h = Math.round(24 + 4 * Math.sin(dx * Math.PI) * Math.cos(dz * Math.PI));
      for (var cy = 23; cy <= h; cy++) {
        block(cx2, cy, cz2, COAL);
      }
    }
  }
  block(103, 29, cz, COAL);
  block(108, 28, cz - 2, COAL);
  block(106, 30, cz + 1, COAL);

  // Tender wheels (upright, FWD="z")
  var twXs = [100, 108];
  for (var ti = 0; ti < twXs.length; ti++) {
    wheel("x", twXs[ti], 8, cz - 7, 3, 1, WHEEL_RIM, BOILER_TRIM);
    wheel("x", twXs[ti], 8, cz + 5, 3, 1, WHEEL_RIM, BOILER_TRIM);
  }

  line(95, 10, cz, 96, 10, cz, BOILER_TRIM);
}

// === Passenger Car ===
function buildPassengerCar(px1, px2) {
  var cz = 128, W = 8;

  box(px1, 8, cz - W + 2, px2, 24, cz + W - 2, CAR_RED);
  box(px1, 8, cz - W + 2, px2, 9, cz + W - 2, TIE);
  box(px1, 16, cz - W + 2, px2, 17, cz + W - 2, CAR_TRIM);
  box(px1, 9, cz - W + 2, px2, 10, cz + W - 2, CAR_TRIM);

  // Curved roof
  for (var ry = 0; ry <= 4; ry++) {
    var rw = Math.round((W - 2) * Math.cos(ry / 4 * Math.PI / 2));
    box(px1, 24 + ry, cz - rw, px2, 24 + ry, cz + rw, ROOF_BRICK);
  }
  box(px1, 28, cz - 1, px2, 29, cz + 1, ROOF_BRICK);

  // Windows (both z sides, y 19-23)
  box(px1 + 2, 19, cz - W + 2, px2 - 2, 23, cz - W + 2, GLASS);
  box(px1 + 2, 19, cz + W - 2, px2 - 2, 23, cz + W - 2, GLASS);
  // Window frames
  for (var wf = px1 + 4; wf <= px2 - 4; wf += 4) {
    box(wf, 19, cz - W + 2, wf, 23, cz - W + 2, CAR_TRIM);
    box(wf, 19, cz + W - 2, wf, 23, cz + W - 2, CAR_TRIM);
  }

  // Door on one end
  box(px2, 10, cz - 2, px2, 22, cz + 2, CAB_WOOD);
  block(px2, 16, cz + 2, GOLD);

  // Undercarriage frame (full-width, extends to y=7 to meet body)
  box(px1 + 2, 0, cz - W + 2, px2 - 2, 7, cz + W - 2, BOILER_TRIM);
  for (var cb = px1 + 4; cb <= px2 - 4; cb += 6) {
    line(cb, 3, cz - W + 2, cb, 7, cz + W - 2, BOILER_TRIM);
  }

  // Wheels (upright, FWD="x")
  var cwXs = [px1 + 6, px1 + 14, px2 - 6];
  for (var ci = 0; ci < cwXs.length; ci++) {
    wheel("x", cwXs[ci], 8, cz - 7, 3, 1, WHEEL_RIM, BOILER_TRIM);
    wheel("x", cwXs[ci], 8, cz + 5, 3, 1, WHEEL_RIM, BOILER_TRIM);
  }

  line(px1 - 1, 10, cz, px2, 10, cz, BOILER_TRIM);
}

// === Track ===
function buildTrack() {
  var cz = 128;
  for (var tx = 10; tx <= 175; tx += 3) {
    box(tx, 2, cz - 3, tx, 2, cz + 3, TIE);
  }
  box(10, 3, cz - 2, 175, 3, cz - 2, RAIL);
  box(10, 3, cz + 2, 175, 3, cz + 2, RAIL);
  for (var sx = 10; sx <= 175; sx += 1) {
    block(sx, 4, cz - 2, BOILER_TRIM);
    block(sx, 4, cz + 2, BOILER_TRIM);
  }
  for (var bx = 8; bx <= 177; bx++) {
    for (var bz = cz - 5; bz <= cz + 5; bz++) {
      if (Math.abs(bz - cz) <= 3 || (bx % 3 === 0)) {
        block(bx, 0, bz, BALLAST);
      }
    }
  }
}

// === Station Platform ===
function buildPlatform() {
  var cz = 128;
  box(140, 1, cz + 9, 175, 4, cz + 20, PLATFORM);
  box(140, 4, cz + 9, 175, 4, cz + 20, PLAT_TRIM);
  box(140, 4, cz + 20, 175, 4, cz + 20, CAR_TRIM);
  box(142, 1, cz + 10, 144, 4, cz + 12, PLAT_TRIM);
  box(166, 1, cz + 10, 168, 4, cz + 12, PLAT_TRIM);
  box(154, 1, cz + 10, 156, 4, cz + 12, PLAT_TRIM);
  box(139, 10, cz + 8, 176, 11, cz + 21, ROOF_BRICK);
  line(143, 4, cz + 11, 139, 10, cz + 8, BOILER_TRIM);
  line(143, 4, cz + 11, 176, 10, cz + 8, BOILER_TRIM);
  line(167, 4, cz + 11, 139, 10, cz + 21, BOILER_TRIM);
  line(167, 4, cz + 11, 176, 10, cz + 21, BOILER_TRIM);
  line(155, 4, cz + 11, 155, 10, cz + 8, BOILER_TRIM);
  line(155, 4, cz + 11, 155, 10, cz + 21, BOILER_TRIM);
}

// === Scene ===
function buildScene() {
  var cz = 128;

  // Ground — rolling terrain with hills
  for (var gx = 0; gx < 256; gx++) {
    for (var gz = 0; gz < 256; gz++) {
      var hill1 = Math.round(2 * Math.sin(gx / 40 * Math.PI) * Math.cos(gz / 35 * Math.PI));
      var hill2 = Math.round(1.5 * Math.sin(gx / 20 * Math.PI + 1) * Math.sin(gz / 25 * Math.PI + 0.5));
      var h = hill1 + hill2;
      var dz = Math.abs(gz - 128);
      var dx_track = Math.abs(gx - 113);
      if (dz < 8 && dx_track < 80) h = Math.max(h, 0);
      if (gx >= 140 && gx <= 175 && gz >= 8 && gz <= 22) h = Math.max(h, 0);
      for (var gy = 0; gy <= h; gy++) {
        if (gy === h) {
          var surfHash = ((gx * 7 + gz * 13) % 5);
          block(gx, gy, gz, surfHash < 4 ? GRASS : DIRT);
        } else {
          block(gx, gy, gz, DIRT);
        }
      }
    }
  }

  // Trees
  function tree(tx, ty, tz, h) {
    box(tx, ty, tz, tx, ty + h - 1, tz, LOG);
    for (var ly = ty + h - 2; ly <= ty + h + 1; ly++) {
      var lr = Math.max(1, Math.round(3 - Math.abs(ly - (ty + h)) * 0.4));
      box(tx - lr, ly, tz - lr, tx + lr, ly, tz + lr, LEAVES);
    }
  }
  tree(20, 0, 152, 9);
  tree(182, 0, 152, 11);
  tree(182, 0, 98, 8);
  tree(52, 0, 158, 10);
  tree(32, 0, 98, 8);
  tree(182, 0, 128, 9);
  tree(15, 0, 120, 7);
  tree(190, 0, 140, 10);

  // Water tower
  box(48, 0, 154, 49, 12, 155, LOG);
  box(52, 0, 154, 53, 12, 155, LOG);
  box(47, 12, 152, 54, 18, 156, BOILER_TRIM);
  box(47, 18, 152, 54, 19, 156, ROOF_BRICK);
  for (var la = 1; la <= 11; la++) {
    block(47, la, 154, BOILER_TRIM);
    block(47, la, 155, BOILER_TRIM);
  }

  // Signal post
  box(138, 0, cz + 11, 138, 12, cz + 11, LOG);
  box(138, 11, cz + 11, 138, 11, cz + 15, SIGNAL_RED);
  box(138, 9, cz + 11, 138, 9, cz + 15, SIGNAL_GREEN);

  // Pond
  for (var px = 175; px <= 186; px++) {
    for (var pz = 88; pz <= 100; pz++) {
      var pdx = px - 180, pdz = pz - 94;
      if (pdx * pdx + pdz * pdz <= 22) {
        block(px, 0, pz, WATER);
      }
    }
  }

  // Fence near platform
  for (var fx = 135; fx <= 138; fx++) {
    box(fx, 1, cz - 6, fx, 3, cz - 6, FENCE);
    box(fx, 2, cz - 6, fx, 2, cz - 4, FENCE);
  }

  // Water trough for locomotive
  box(18, 1, cz + 5, 28, 3, cz + 9, PLATFORM);
  box(19, 2, cz + 6, 27, 3, cz + 8, WATER);
  box(18, 0, cz + 5, 18, 1, cz + 9, PLAT_TRIM);
  box(28, 0, cz + 5, 28, 1, cz + 9, PLAT_TRIM);

  // Platform bench
  box(150, 5, cz + 14, 154, 6, cz + 16, CAB_WOOD);
  box(150, 6, cz + 14, 150, 8, cz + 16, CAB_WOOD);
  box(154, 6, cz + 14, 154, 8, cz + 16, CAB_WOOD);

  // Station sign
  box(136, 5, cz + 14, 136, 9, cz + 14, FENCE);
  box(134, 10, cz + 13, 138, 11, cz + 15, CAB_WOOD);
  block(135, 10, cz + 14, GOLD);
  block(136, 10, cz + 14, GOLD);
  block(137, 10, cz + 14, GOLD);
}

// === Run ===
buildLocomotive();
buildTender();
buildPassengerCar(116, 137);
buildPassengerCar(139, 160);
buildTrack();
buildPlatform();
buildScene();
